 $wpdb->delete($wpdb->postmeta,['post_id'=>$report]);$wpdb->delete($wpdb->posts,['ID'=>$report]);unlink($folder.'/report.pdf');wp_cache_flush();$review=$must(B::inspect($backup));$must(B::restore($backup,$review['sha256'],$review['revision'],true));$ok(get_post($report)->post_type==='attachment' && file_get_contents($folder.'/report.pdf')==='REPORT ORIGINAL','deleted selected attachment and cover-parent link restored with original IDs');
