 update_post_meta($other,'_wp_attached_file',$relative.'/photo.jpg');$ok(is_wp_error(B::create(['media'],[$image])) && is_wp_error(B::inspect($backup)),'shared path outside selected attachments blocks backup and restore review');update_post_meta($other,'_wp_attached_file',$relative.'/other.pdf');
